-- 129: Original BrillaPrep WASSCE BrillaPrep IRS beta content blueprint beta questions, part 8.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_129_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_129_guard;
INSERT INTO _migration_129_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_036' AND NOT (q.topic_id IS 'topic_was_irs_8' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does amanah require in business dealings?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Concealing defects from buyers","B. Changing agreed measures secretly","C. Breaking promises whenever profit increases","D. Trustworthiness and faithful discharge of responsibility"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Amanah requires honesty with property, information and obligations, making it central to trustworthy trade and public responsibility. Therefore the correct answer is D: Trustworthiness and faithful discharge of responsibility.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_036' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_129_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_037' AND NOT (q.topic_id IS 'topic_was_irs_8' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What social purpose does Zakah serve?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Purifying qualifying wealth and supporting eligible people and causes","B. Increasing inequality as an objective","C. Replacing every voluntary good deed","D. Funding only luxury consumption"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Zakah combines worship with structured social support and reminds owners that wealth carries duties toward the wider community. Therefore the correct answer is A: Purifying qualifying wealth and supporting eligible people and causes.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_037' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_129_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_038' AND NOT (q.topic_id IS 'topic_was_irs_8' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which conduct best reflects adl?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Favouring relatives regardless of evidence","B. Acting justly even when personal interest points elsewhere","C. Using different measures for buyers and sellers","D. Withholding every worker’s agreed wage"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Adl means justice and fairness. Islamic ethics require consistent standards and protection of rights rather than biased advantage. Therefore the correct answer is B: Acting justly even when personal interest points elsewhere.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_038' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_129_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_039' AND NOT (q.topic_id IS 'topic_was_irs_8' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How should disagreement be handled according to Islamic ethics?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. With insults and deliberate falsehood","B. By assuming every opponent is dishonest","C. With evidence, respectful speech and a sincere search for reconciliation","D. By spreading unverified accusations"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Truthfulness, restraint and peacemaking protect dignity and make resolution more likely even when the parties continue to disagree. Therefore the correct answer is C: With evidence, respectful speech and a sincere search for reconciliation.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_8' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_039' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_129_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_040' AND NOT (q.topic_id IS 'topic_was_irs_8' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does stewardship of the earth imply?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Natural resources have no moral value","B. Waste is acceptable when ownership is private","C. Future generations have no interests","D. People should use resources responsibly and avoid waste and harm"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The idea of khalifah frames human power as accountable stewardship, encouraging beneficial use, moderation and protection from corruption or needless damage. Therefore the correct answer is D: People should use resources responsibly and avoid waste and harm.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_040' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_irs_b001_036', 'topic_was_irs_8', 'subj_wassce_irs', 'exam_wassce', NULL, NULL, 'What does amanah require in business dealings?', 'multiple_choice', NULL, '["A. Concealing defects from buyers","B. Changing agreed measures secretly","C. Breaking promises whenever profit increases","D. Trustworthiness and faithful discharge of responsibility"]', 'D', 'Amanah requires honesty with property, information and obligations, making it central to trustworthy trade and public responsibility. Therefore the correct answer is D: Trustworthiness and faithful discharge of responsibility.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_irs_8', 'Identify', 'AO3', NULL, NULL, 'board_waec');
